        self.root = {}

    def addWord(self, word: str) -> None:
        node = self.root
        for c in word:
            node = node.setdefault(c, {})
        node["$"] = True

    def search(self, word: str) -> bool:
        def dfs(node, i):
            if i == len(word):
                return "$" in node
            c = word[i]
            if c != ".":
                return c in node and dfs(node[c], i + 1)
            return any(dfs(child, i + 1) for key, child in node.items() if key != "$")
        return dfs(self.root, 0)

