                int mid = (lo + hi) >>> 1;
                if (products[mid].compareTo(prefix) < 0) lo = mid + 1; else hi = mid;
            }
            List<String> match = new ArrayList<>();
            for (int i = lo; i < Math.min(lo + 3, products.length) && products[i].startsWith(prefix); i++) match.add(products[i]);
            out.add(match);
        }
        return out;
    }
}

