        root = {}
        for w in words:
            node = root
            for c in w:
                node = node.setdefault(c, {})
            node["$"] = w
        m, n, out = len(board), len(board[0]), []
        def dfs(r, c, parent):
            if r < 0 or c < 0 or r >= m or c >= n:
                return
            ch = board[r][c]
            node = parent.get(ch)
            if node is None:
                return
            if "$" in node:
                out.append(node.pop("$"))
            board[r][c] = "#"
            dfs(r + 1, c, node)
            dfs(r - 1, c, node)
            dfs(r, c + 1, node)
            dfs(r, c - 1, node)
            board[r][c] = ch
        for r in range(m):
            for c in range(n):
                dfs(r, c, root)
        return out

